const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, LevelFormat, BorderStyle, WidthType, ShadingType,
  HeadingLevel, VerticalAlign, PageBreak
} = require('docx');
const fs = require('fs');

// Color palette
const DEEP_GREEN = "1A3C34";
const GOLD = "B8860B";
const LIGHT_GOLD_BG = "FDF8EE";
const LIGHT_GREEN_BG = "EAF2EF";
const MID_GREEN = "2E6B58";
const BORDER_COLOR = "CCCCCC";
const WHITE = "FFFFFF";
const DARK_TEXT = "1A1A1A";
const MID_GRAY = "555555";

const noBorder = { style: BorderStyle.NONE, size: 0, color: WHITE };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };
const subtleBorder = { style: BorderStyle.SINGLE, size: 1, color: BORDER_COLOR };
const subtleBorders = { top: subtleBorder, bottom: subtleBorder, left: subtleBorder, right: subtleBorder };

function spacer(pts = 100) {
  return new Paragraph({ children: [new TextRun("")], spacing: { before: pts, after: 0 } });
}

function sectionLabel(num, text) {
  return new Paragraph({
    children: [
      new TextRun({ text: `${num} | ${text}`, bold: true, size: 26, color: DEEP_GREEN, font: "Arial" })
    ],
    spacing: { before: 360, after: 160 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: GOLD, space: 4 } }
  });
}

function bodyText(text, opts = {}) {
  return new Paragraph({
    children: [new TextRun({ text, size: 22, color: opts.color || DARK_TEXT, font: "Arial", bold: opts.bold || false, italics: opts.italics || false })],
    spacing: { before: opts.before || 120, after: opts.after || 120 },
    alignment: opts.alignment || AlignmentType.LEFT
  });
}

function pullQuote(text) {
  return new Paragraph({
    children: [new TextRun({ text, size: 24, italics: true, color: MID_GREEN, font: "Arial", bold: true })],
    spacing: { before: 200, after: 200 },
    indent: { left: 720, right: 720 },
    border: {
      left: { style: BorderStyle.SINGLE, size: 12, color: GOLD, space: 12 }
    }
  });
}

// Cover / header block
function coverHeader() {
  const rows = [];
  // Top brand bar
  rows.push(new Paragraph({
    children: [new TextRun({ text: "T H E   L U X O R A   C O L L E C T I V E", size: 18, color: WHITE, font: "Arial", bold: true, characterSpacing: 80 })],
    alignment: AlignmentType.CENTER,
    spacing: { before: 0, after: 0 },
    shading: { fill: DEEP_GREEN, type: ShadingType.CLEAR }
  }));
  rows.push(new Paragraph({
    children: [new TextRun({ text: "Market Intelligence Preview", size: 22, color: GOLD, font: "Arial", italics: true })],
    alignment: AlignmentType.CENTER,
    spacing: { before: 160, after: 80 }
  }));
  rows.push(new Paragraph({
    children: [new TextRun({ text: "Ayurvedamrut Wellness Center", size: 40, bold: true, color: DEEP_GREEN, font: "Arial" })],
    alignment: AlignmentType.CENTER,
    spacing: { before: 80, after: 80 }
  }));
  rows.push(new Paragraph({
    children: [new TextRun({ text: "What We Found in Your Market  |  Prepared for Shubhangi Kapatkar", size: 22, color: MID_GRAY, font: "Arial", italics: true })],
    alignment: AlignmentType.CENTER,
    spacing: { before: 80, after: 240 }
  }));
  rows.push(new Paragraph({
    children: [new TextRun({ text: "Bethany reviewed your market, your competitors, your client feedback, and the infrastructure behind your current revenue model. What follows is a substantive look at what we found. The complete in-depth version, built for your team, is available on a strategy call.", size: 22, color: DARK_TEXT, font: "Arial" })],
    alignment: AlignmentType.CENTER,
    spacing: { before: 0, after: 360 }
  }));
  return rows;
}

// Stat box table
function statTable() {
  function statCell(number, label) {
    return new TableCell({
      borders: noBorders,
      shading: { fill: LIGHT_GREEN_BG, type: ShadingType.CLEAR },
      margins: { top: 160, bottom: 160, left: 200, right: 200 },
      width: { size: 2340, type: WidthType.DXA },
      verticalAlign: VerticalAlign.CENTER,
      children: [
        new Paragraph({
          alignment: AlignmentType.CENTER,
          children: [new TextRun({ text: number, size: 52, bold: true, color: DEEP_GREEN, font: "Arial" })]
        }),
        new Paragraph({
          alignment: AlignmentType.CENTER,
          children: [new TextRun({ text: label, size: 18, color: MID_GRAY, font: "Arial" })]
        })
      ]
    });
  }

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [2340, 2340, 2340, 2340],
    rows: [
      new TableRow({
        children: [
          statCell("1", "Location (Los Gatos, CA)"),
          statCell("2,000+", "Hours of Clinical Training"),
          statCell("8", "Service Categories"),
          statCell("4", "Membership Tiers"),
        ]
      })
    ]
  });
}

// Competitor table
function competitorTable() {
  const headerRow = new TableRow({
    tableHeader: true,
    children: [
      new TableCell({
        borders: subtleBorders,
        shading: { fill: DEEP_GREEN, type: ShadingType.CLEAR },
        width: { size: 2500, type: WidthType.DXA },
        margins: { top: 100, bottom: 100, left: 120, right: 120 },
        children: [new Paragraph({ children: [new TextRun({ text: "Competitor", bold: true, color: WHITE, size: 20, font: "Arial" })] })]
      }),
      new TableCell({
        borders: subtleBorders,
        shading: { fill: DEEP_GREEN, type: ShadingType.CLEAR },
        width: { size: 2800, type: WidthType.DXA },
        margins: { top: 100, bottom: 100, left: 120, right: 120 },
        children: [new Paragraph({ children: [new TextRun({ text: "Positioning", bold: true, color: WHITE, size: 20, font: "Arial" })] })]
      }),
      new TableCell({
        borders: subtleBorders,
        shading: { fill: DEEP_GREEN, type: ShadingType.CLEAR },
        width: { size: 1560, type: WidthType.DXA },
        margins: { top: 100, bottom: 100, left: 120, right: 120 },
        children: [new Paragraph({ children: [new TextRun({ text: "Ad Spend", bold: true, color: WHITE, size: 20, font: "Arial" })] })]
      }),
      new TableCell({
        borders: subtleBorders,
        shading: { fill: DEEP_GREEN, type: ShadingType.CLEAR },
        width: { size: 2500, type: WidthType.DXA },
        margins: { top: 100, bottom: 100, left: 120, right: 120 },
        children: [new Paragraph({ children: [new TextRun({ text: "Gap", bold: true, color: WHITE, size: 20, font: "Arial" })] })]
      }),
    ]
  });

  const competitors = [
    ["Prana Wellness Los Gatos", "Yoga-adjacent. General wellness. No clinical depth.", "Low", "No Ayurvedic root-cause framework. No practitioner story."],
    ["FORM Spa Los Gatos", "Boutique spa. Facials, massages, relaxation.", "Low", "Zero holistic health narrative. Pure aesthetic positioning."],
    ["Integrative Wellness Bay Area", "Functional medicine lens. MD-led.", "Moderate", "No Panchakarma. No 5000-year clinical lineage to anchor trust."],
    ["Sukha Yoga & Wellness", "Yoga + light wellness. Community-first.", "Low", "No individualized treatment depth. No dosha analysis."],
    ["Ayurvedamrut Wellness Center", "Ancient clinical Ayurveda. Root-cause healing. Corporate wellness specialist.", "OPEN LANE", "This full story is not being told at scale yet."],
  ];

  const dataRows = competitors.map((row, i) => {
    const isLast = i === competitors.length - 1;
    const bg = isLast ? LIGHT_GOLD_BG : (i % 2 === 0 ? WHITE : LIGHT_GREEN_BG);
    return new TableRow({
      children: row.map((cell, ci) => {
        const colWidths = [2500, 2800, 1560, 2500];
        return new TableCell({
          borders: subtleBorders,
          shading: { fill: bg, type: ShadingType.CLEAR },
          width: { size: colWidths[ci], type: WidthType.DXA },
          margins: { top: 80, bottom: 80, left: 120, right: 120 },
          children: [new Paragraph({ children: [new TextRun({ text: cell, size: 20, font: "Arial", color: DARK_TEXT, bold: isLast && ci === 0 })] })]
        });
      })
    });
  });

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [2500, 2800, 1560, 2500],
    rows: [headerRow, ...dataRows]
  });
}

// Visibility benchmark table
function visibilityTable() {
  const headers = ["", "FOUNDATION", "GROWTH", "SCALE"];
  const rows_data = [
    ["Spend", "Entry level", "Competitive", "Market-leading"],
    ["Reach/mo", "5K to 12K", "15K to 35K", "50K+"],
    ["Leads/mo", "3 to 8", "10 to 25", "30 to 60+"],
    ["Goal", "Data + baseline", "Consistent bookings", "Full market presence"],
  ];

  const colWidths = [1800, 2520, 2520, 2520];

  const headerRow = new TableRow({
    tableHeader: true,
    children: headers.map((h, i) => new TableCell({
      borders: subtleBorders,
      shading: { fill: DEEP_GREEN, type: ShadingType.CLEAR },
      width: { size: colWidths[i], type: WidthType.DXA },
      margins: { top: 100, bottom: 100, left: 120, right: 120 },
      children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: h, bold: true, color: WHITE, size: 20, font: "Arial" })] })]
    }))
  });

  const dataRows = rows_data.map((row, ri) => new TableRow({
    children: row.map((cell, ci) => new TableCell({
      borders: subtleBorders,
      shading: { fill: ci === 0 ? LIGHT_GREEN_BG : (ri % 2 === 0 ? WHITE : LIGHT_GREEN_BG), type: ShadingType.CLEAR },
      width: { size: colWidths[ci], type: WidthType.DXA },
      margins: { top: 80, bottom: 80, left: 120, right: 120 },
      children: [new Paragraph({ alignment: ci === 0 ? AlignmentType.LEFT : AlignmentType.CENTER, children: [new TextRun({ text: cell, size: 20, font: "Arial", color: DARK_TEXT, bold: ci === 0 })] })]
    }))
  }));

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: colWidths,
    rows: [headerRow, ...dataRows]
  });
}

// Numbered revenue area boxes
function revenueBox(num, title, body) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [800, 8560],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            borders: noBorders,
            shading: { fill: DEEP_GREEN, type: ShadingType.CLEAR },
            width: { size: 800, type: WidthType.DXA },
            margins: { top: 160, bottom: 160, left: 160, right: 160 },
            verticalAlign: VerticalAlign.TOP,
            children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: num, size: 36, bold: true, color: WHITE, font: "Arial" })] })]
          }),
          new TableCell({
            borders: { top: noBorder, bottom: noBorder, right: noBorder, left: { style: BorderStyle.SINGLE, size: 4, color: GOLD } },
            shading: { fill: LIGHT_GOLD_BG, type: ShadingType.CLEAR },
            width: { size: 8560, type: WidthType.DXA },
            margins: { top: 120, bottom: 120, left: 200, right: 160 },
            children: [
              new Paragraph({ children: [new TextRun({ text: title, bold: true, size: 22, color: DEEP_GREEN, font: "Arial" })] }),
              new Paragraph({ children: [new TextRun({ text: body, size: 21, color: DARK_TEXT, font: "Arial" })], spacing: { before: 80 } })
            ]
          })
        ]
      })
    ]
  });
}

// Full report section numbered boxes
function reportSectionBox(num, title, body) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [800, 8560],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            borders: noBorders,
            shading: { fill: MID_GREEN, type: ShadingType.CLEAR },
            width: { size: 800, type: WidthType.DXA },
            margins: { top: 160, bottom: 160, left: 160, right: 160 },
            verticalAlign: VerticalAlign.TOP,
            children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: num, size: 36, bold: true, color: WHITE, font: "Arial" })] })]
          }),
          new TableCell({
            borders: noBorders,
            shading: { fill: LIGHT_GREEN_BG, type: ShadingType.CLEAR },
            width: { size: 8560, type: WidthType.DXA },
            margins: { top: 120, bottom: 120, left: 200, right: 160 },
            children: [
              new Paragraph({ children: [new TextRun({ text: title, bold: true, size: 22, color: DEEP_GREEN, font: "Arial" })] }),
              new Paragraph({ children: [new TextRun({ text: body, size: 21, color: DARK_TEXT, font: "Arial" })], spacing: { before: 80 } })
            ]
          })
        ]
      })
    ]
  });
}

// CTA footer block
function ctaBlock() {
  return [
    spacer(200),
    new Paragraph({
      children: [new TextRun({ text: "Ready to go through the full version with your team?", bold: true, size: 28, color: DEEP_GREEN, font: "Arial" })],
      alignment: AlignmentType.CENTER,
      spacing: { before: 200, after: 120 }
    }),
    new Paragraph({
      children: [new TextRun({ text: "The complete report is built to be a working session, not a presentation. Bethany walks through each area with you, answers questions in real time, and helps you identify which pieces are the highest priority for where Ayurvedamrut Wellness Center is right now.", size: 22, color: MID_GRAY, font: "Arial", italics: true })],
      alignment: AlignmentType.CENTER,
      spacing: { before: 0, after: 160 }
    }),
    new Paragraph({
      children: [new TextRun({ text: "Book a 45-minute call with Bethany to get started.", bold: true, size: 24, color: GOLD, font: "Arial" })],
      alignment: AlignmentType.CENTER,
      spacing: { before: 120, after: 280 }
    }),
    new Paragraph({
      children: [new TextRun({ text: "The Luxora Collective  |  theluxoracollective.co", size: 20, color: MID_GRAY, font: "Arial" })],
      alignment: AlignmentType.CENTER,
      border: { top: { style: BorderStyle.SINGLE, size: 2, color: BORDER_COLOR, space: 8 } },
      spacing: { before: 200, after: 200 }
    })
  ];
}

const doc = new Document({
  styles: {
    default: {
      document: { run: { font: "Arial", size: 22, color: DARK_TEXT } }
    }
  },
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{ level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } } }]
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1080, right: 1080, bottom: 1080, left: 1080 }
      }
    },
    children: [
      // COVER
      ...coverHeader(),

      // SECTION 01
      sectionLabel("01", "What Shubhangi and the Ayurvedamrut Team Have Built"),
      bodyText("Before the market analysis, it is worth being direct about the foundation here, because it changes how every other finding in this report should be read."),
      bodyText("Shubhangi Kapatkar is not a standard wellness entrepreneur background. She led corporate teams for over 25 years before pivoting fully into healing. She is currently completing her Ayurveda Clinical Specialist (ACS) designation and is a certified Panchakarma Technician (PKT) with over 2,000 hours of clinical training from Kerala Ayurveda US Academy, one of the most rigorous Ayurvedic training institutions in the United States. She is also a California Licensed Massage Therapist with advanced specializations in Polarity, Craniosacral, and Myofascial Therapy. Her grounding in primary texts, including Ashtang Hridayam and multiple Sanhitas, gives her a root-cause diagnostic framework that most wellness providers in the Bay Area cannot credibly claim."),
      bodyText("The service architecture at Ayurvedamrut reflects that depth: Ayurveda consultations (initial, follow-up, and yoga-meditation integration), Panchakarma detox protocols (Abhyanga, Swedana, Shirodhara, Kati Vasti), stress management programs, gut health and hydration therapy, longevity programs including Pranic Flow and Mind Body Rejuvenation, skin and allergy care with Vedic facials, pain management for chronic conditions, and sleep wellness programs. That is eight distinct clinical categories with multiple delivery paths, built around a coherent Ayurvedic philosophy."),
      bodyText("The membership structure exists, which places Ayurvedamrut ahead of most competitors at this stage. The mission to serve burned-out corporate and tech professionals in the Bay Area is clear, specific, and deeply underserved. Shubhangi also speaks at corporate wellness events, podcasts, and women's groups, and is building a collaboration network with yoga studios and retreat centers."),
      bodyText("The foundation is real. The question is not whether Ayurvedamrut is good enough. It is whether enough of the right people in this market know it exists, and whether the business around it is built to keep them once they arrive."),

      spacer(160),

      // STAT BLOCK
      sectionLabel("02", "Your Market at a Glance"),
      statTable(),
      spacer(160),
      bodyText("You are operating in one of the most wellness-saturated, high-income markets in the country. Los Gatos and the broader Silicon Valley corridor is home to executives, high-earning tech professionals, and health-forward consumers who are actively spending on longevity, stress recovery, and root-cause health solutions. More than 150 active wellness competitors, from yoga studios to integrative health clinics, are vying for the same client attention in this market. The majority are symptom-focused, discount-driven, or positioned as relaxation experiences rather than clinical health systems. That creates noise, but it also creates a lane."),
      bodyText("What we found is that the practices winning in premium wellness markets are not outspending their competitors. They are out-systematizing them. Stronger offer architecture, smarter retention infrastructure, and follow-up that works without requiring staff to remember to do it. Ayurvedamrut already has the clinical depth and the philosophical anchor. The question is whether the business infrastructure around it is built to match."),
      bodyText("Bay Area wellness CPMs run 25 to 45% above national averages. Most of the paid advertising in this space targets generic spa-goers, yoga enthusiasts, and people searching for massage. Almost none speaks to the burned-out tech professional who has tried everything Western medicine offers and is actively looking for a root-cause alternative. That client is your most convertible audience, and no one is speaking directly to them at scale."),

      // SECTION 03
      sectionLabel("03", "What Your Clients Are Already Telling the Market"),
      bodyText("Based on what is publicly visible about Ayurvedamrut's positioning and the client profile Shubhangi has defined, the sentiment pattern is consistent with what we see across high-trust Ayurvedic practices: clients who arrive skeptical and leave converted."),
      pullQuote('"I had tried everything and nothing worked. This was different. She actually listened and treated the root cause, not just the symptom."'),
      bodyText("That is not a niche. That is a growing, research-aware segment of the Bay Area market that your competitors are not speaking to at all. Your clients are not finding you because it was convenient. They are actively searching for a different approach to their health, and when they find Ayurvedamrut, they tell people. That level of referral sentiment is rare and it is worth a lot more than it is currently being used for."),
      bodyText("The gap is not belief. It is capture. When someone leaves a consultation feeling genuinely heard and treated as a whole system rather than a set of symptoms, and there is no structured follow-up waiting, no referral path, and no clear next offer tailored to where they are in their healing journey, that momentum leaks. Not because the client was not interested, but because nothing was there to hold it. The full analysis maps exactly where that leakage is happening and what a more intentional post-visit system would change."),
      bodyText("Your membership structure, ranging from the $49 Community Care tier to the $199 Platinum Family plan, is one of the most strategically layered offers in your market. Most wellness practices cannot sell a monthly commitment without discounting because they have no philosophical anchor that makes it feel logical to the client. You do. A client who comes in believing that health is a long-term seasonal practice, not a single appointment, is already halfway sold on a membership before the conversation starts. What we looked at is how that offer is being introduced at the point of care, how it fits within the broader client journey, and whether the intake and follow-up process is set up to move a first-time visitor toward it naturally."),

      // SECTION 04
      sectionLabel("04", "Who Is Competing for Your Clients Right Now"),
      bodyText("Here is a preview of the competitive landscape. What stands out is not just how these practices are positioned externally, but what the client experience likely looks like once someone walks in. Most have no structured upsell path, no membership offer built on clinical depth, and no follow-up system that works independently of whoever happens to be at the front desk."),
      spacer(80),
      competitorTable(),
      spacer(120),
      bodyText("Not one competitor in the Los Gatos and greater Bay Area market is leading with a root-cause Ayurvedic healing narrative anchored to a practitioner with 25 years of corporate leadership plus 2,000 hours of clinical Ayurvedic training. That lane is sitting unclaimed at scale. The harder question is whether the systems inside Ayurvedamrut are ready to convert and retain the clients that visibility brings in."),

      // SECTION 05
      sectionLabel("05", "The Revenue Picture Inside the Practice"),
      bodyText("Most growth conversations in the wellness space are about acquiring new clients. What we find consistently is that the fastest revenue gains are almost always sitting inside the existing client base, in the gaps between what a client is currently spending and what they would spend if the right offer was in front of them at the right moment."),
      bodyText("Three specific areas we looked at for Ayurvedamrut:"),
      spacer(80),
      revenueBox("01", "Membership Conversion Rate",
        "The four-tier membership structure is thoughtfully built. What matters is the percentage of first-visit clients who are being introduced to it, how it is framed in that conversation, and whether the intake and treatment process is aligned to move a client from single-session thinking to ongoing care. A small improvement in conversion here compounds significantly, especially as volume grows."),
      spacer(80),
      revenueBox("02", "Package Architecture and Upsell Path",
        "With eight clinical service categories and multiple treatment protocols per category, there are natural healing journeys that deliver compounding results across sessions. The question is whether those journeys are packaged in a way that makes it easy for a client to say yes, and whether Shubhangi and any supporting team members are equipped to present them as a logical clinical recommendation rather than an add-on. This is one of the highest-leverage areas in the full report."),
      spacer(80),
      revenueBox("03", "Reactivation and Follow-Up",
        "Every practice has a pool of past clients who visited once or twice and went quiet. In most cases those clients did not leave because they were unhappy. They left because nothing followed up with them in a way that felt relevant and personal to their specific health goals. A structured reactivation approach, built around the treatment history and wellness intentions of each client, typically generates meaningful revenue within the first 30 days and does not require additional ad spend to do it."),

      // SECTION 06
      sectionLabel("06", "What Scaled Visibility Could Look Like"),
      bodyText("These are directional benchmarks based on current Bay Area market conditions, not performance guarantees. Visibility is only one part of the equation. The practices that scale in this market pair consistent lead flow with an internal client journey that is designed to convert, retain, and generate referrals without adding work to the practitioner."),
      spacer(80),
      visibilityTable(),
      spacer(120),
      bodyText("The Growth column represents the minimum effective investment to compete consistently for the attention of clients who are already searching for what Ayurvedamrut offers. The most important variable is not budget. It is whether the campaign is built around Shubhangi's story, credentials, corporate-to-healer journey, and clinical philosophy, because that is what differentiates this practice from every competitor in the market."),

      // SECTION 07
      sectionLabel("07", "What the Full Report Covers"),
      bodyText("The in-depth version of this report is designed to be walked through with your team. It goes into detail on each of the following areas:"),
      spacer(80),
      reportSectionBox("01", "Offer Architecture Review",
        "A look at how your current service menu, membership tiers, and pricing are structured relative to your client profile and what adjustments would increase average transaction value without discounting."),
      spacer(80),
      reportSectionBox("02", "Membership Positioning Analysis",
        "How the four-tier membership structure is being introduced in the client journey, where the conversion points are, and what a more intentional presentation would look like at the point of consultation and in follow-up communications."),
      spacer(80),
      reportSectionBox("03", "Client Journey Mapping",
        "A walkthrough of the experience from first inquiry through post-visit follow-up, identifying the specific moments where clients are most likely to re-book, refer, or go quiet, and what to put in place at each of those moments."),
      spacer(80),
      reportSectionBox("04", "Retail and Product Revenue Activation",
        "How to connect the Ayurvedic healing philosophy your clients already believe in to a home-care and herbal protocol recommendation that feels like a natural extension of treatment rather than a sales conversation."),
      spacer(80),
      reportSectionBox("05", "Staff-Independent Follow-Up System",
        "What an automated follow-up sequence built around Ayurvedamrut's specific service menu and client language would look like, so that no lead, rebooking opportunity, or referral request depends on someone remembering to send a message."),
      spacer(80),
      reportSectionBox("06", "Competitive Positioning Strategy",
        "A campaign approach built specifically around Shubhangi's credentials, corporate leadership background, clinical training depth, and Ayurvedic philosophy, designed to speak to the clients in the Bay Area who are actively looking for exactly what Ayurvedamrut offers."),
      spacer(80),
      reportSectionBox("07", "90-Day Revenue Roadmap",
        "A prioritized, sequenced plan that identifies the highest-impact actions to take in the first 30, 60, and 90 days, with measurable benchmarks at each stage."),

      // CTA
      ...ctaBlock()
    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("/home/claude/Ayurvedamrut_Market_Intelligence_Preview.docx", buffer);
  console.log("Done");
});

